// Ported from the Node app's Sequelize model BookIssue (first generated by tools/gen-efcore.mjs).
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata.Builders;
using SchoolERP.Domain.Entities;

namespace SchoolERP.Infrastructure.Persistence.Configurations;

internal sealed class BookIssueConfiguration : IEntityTypeConfiguration<BookIssue>
{
    public void Configure(EntityTypeBuilder<BookIssue> builder)
    {
        builder.ToTable("book_issues");
        builder.ConfigureAudit();
        builder.HasQueryFilter(e => !e.Delstatus);
        builder.HasKey(e => e.Id);
        builder.Property(e => e.Id).HasColumnName("id").UseIdentityColumn();
        builder.Property(e => e.BookId).HasColumnName("book_id");
        builder.Property(e => e.StudentId).HasColumnName("student_id");
        builder.Property(e => e.IssuedOn).HasColumnName("issued_on").HasColumnType("date");
        builder.Property(e => e.DueOn).HasColumnName("due_on").HasColumnType("date");
        builder.Property(e => e.ReturnedOn).HasColumnName("returned_on").HasColumnType("date");
        builder.Property(e => e.Fine).HasColumnName("fine").HasColumnType("decimal(8,2)").HasDefaultValueSql("0");
        builder.HasOne(e => e.Book).WithMany(p => p.BookIssues).HasForeignKey(e => e.BookId).OnDelete(DeleteBehavior.NoAction);
        builder.HasOne(e => e.Student).WithMany(p => p.BookIssues).HasForeignKey(e => e.StudentId).OnDelete(DeleteBehavior.NoAction);
    }
}
